"""Roster / Mythical stables art (your painted barn sheet): background, stall, gold stall, bars and padlock, long brass plate, wooden button.
img(name) gives the surface; scaled(name, w, h) a cached resized copy."""
import base64
import io
import pygame

# fractions of the stall piece (both stall and stall_gold share them)
OPENING = (0.088, 0.075, 0.912, 0.73)    # the dark open inside (left, top, right, bottom)
PLATE = (0.09, 0.745, 0.91, 0.955)       # the brass name plate across its bottom
LIGHTS = ((553, 40, 48), (1290, 40, 48), (1765, 205, 40))   # torches and lantern in stable_bg.jpg
PNG = {
  'brass_long': ('png', ''),
  'stable_bg': ('jpg', ''),
  'stall': ('png', ''),
  'stall_bars': ('png', ''),
  'stall_gold': ('png', ''),
  'wood_button': ('png', ''),
}
_C = {}


def has(name):
  return name in PNG


def img(name):
  s = _C.get(name)
  if s is None:
    ext, data = PNG[name]
    s = pygame.image.load(io.BytesIO(base64.b64decode(data)), 'art.' + ext)
    try:
      s = s.convert_alpha()
    except Exception:
      pass
    _C[name] = s
  return s


def scaled(name, w, h, smooth=True):
  k = (name, int(w), int(h))
  s = _C.get(k)
  if s is None:
    src = img(name)
    fn = getattr(pygame.transform, 'smoothscale', None) if smooth else None
    try:
      s = (fn or pygame.transform.scale)(src, (max(1, int(w)), max(1, int(h))))
    except Exception:
      s = pygame.transform.scale(src, (max(1, int(w)), max(1, int(h))))
    _C[k] = s
  return s
